-- ============================================================
--  migrate 71b — 기존 서명 파일 실물을 tbl_user.sign_img(bytea)로 이관
--
--  개발자: 박승우
--  일자: 2026-08-12
--  코멘트:
--    1) 71(DDL) 적용 후 실행한다. DB가 원격이라 pg_read_binary_file을 못 쓰므로
--       로컬 PNG를 base64로 인라인해 decode(...,'base64')로 넣는다
--    2) sign_img IS NULL 조건을 붙여 이미 이관된 사용자는 건너뛴다(재실행 안전)
--    3) sign_path는 80(최종 DROP)까지 그대로 남긴다 — 회귀 실패 시 파일 방식으로 되돌릴 수 있게
-- ============================================================

SET search_path TO sasshaccp;

-- admin — 원본 HACCP서명.png (16492 bytes)
UPDATE tbl_user SET sign_img = decode('', 'base64'),
       sign_mime = 'image/png',
       sign_nm = 'HACCP서명.png',
       upd_id = 'system', upd_dt = now()
 WHERE user_id = 'admin' AND sign_img IS NULL;

-- smoke — 원본 HACCP서명.png (16492 bytes)
UPDATE tbl_user SET sign_img = decode('', 'base64'),
       sign_mime = 'image/png',
       sign_nm = 'HACCP서명.png',
       upd_id = 'system', upd_dt = now()
 WHERE user_id = 'smoke' AND sign_img IS NULL;

-- write — 원본 HACCP서명.png (16492 bytes)
UPDATE tbl_user SET sign_img = decode('', 'base64'),
       sign_mime = 'image/png',
       sign_nm = 'HACCP서명.png',
       upd_id = 'system', upd_dt = now()
 WHERE user_id = 'write' AND sign_img IS NULL;

-- 검증 — 이관된 서명 크기
SELECT user_id, sign_mime, sign_nm, octet_length(sign_img) AS sign_bytes
  FROM tbl_user
 WHERE sign_img IS NOT NULL
 ORDER BY user_id;
